arguments.command:
python -c "
# Check what Python's str.format does with {{abc}
try:
    result = '{{abc}}'.format()
    print(f'Python format of \"{{{{abc}}}}\" = {repr(result)}')
except Exception as e:
    print(f'Error: {e}')

try:
    result = '{{abc}'.format()
    print(f'Python format of \"{{{{abc}\" = {repr(result)}')
except Exception as e:
    print(f'Error for {{{{abc}}}: {e}')
" 2>&1
